pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 initialDeposit, address sender) public {
        vm.assume(sender != address(0));
        vm.assume(sender != address(c));
        // Bound to avoid overflow and keep the test in a reasonable range, still wide enough to include any positive amount.
        initialDeposit = bound(initialDeposit, 1, 1000 ether);

        // Fund the sender and deposit into the contract so withdrawAll has something to withdraw.
        vm.deal(sender, initialDeposit);
        vm.prank(sender);
        (bool okDeposit,) = address(c).call{value: initialDeposit}("");
        require(okDeposit, "deposit failed");

        uint contractBalanceBefore = address(c).balance;
        uint ownerBalanceBefore = c.owner().balance;

        // Call withdrawAll as the owner. The owner is the test contract itself (deployer).
        try c.withdrawAll() {
            // Not actually needed, just drives the state change.
        } catch {}

        uint contractBalanceAfter = address(c).balance;
        uint ownerBalanceAfter = c.owner().balance;

        // The invariant: all Ether that left the contract (contractBalanceBefore - contractBalanceAfter)
        // should be equal to the Ether the owner received (ownerBalanceAfter - ownerBalanceBefore).
        // Rearranged: contractBalanceBefore + ownerBalanceBefore == contractBalanceAfter + ownerBalanceAfter
        // For the reference, this holds for every input. The buggy version sends 0, so the inequality
        // holds for any positive initial deposit.
        assertTrue(contractBalanceBefore + ownerBalanceBefore == contractBalanceAfter + ownerBalanceAfter);
    }
}

